// Modo Ask: o agente só conversa e explica. O modo força a leitura (nada é alterado)
// e acrescenta uma instrução ao pedido. A permissão "modes" só restringe, nunca amplia.
export function activate(api) {
  api.registerMode({
    id: "ask",
    label: "Conversar",
    description: "Só conversa: explica e responde, sem editar arquivos nem rodar comandos que alterem algo.",
    instruction:
      "Modo Conversar: responda só com explicações e perguntas. Não edite nem crie arquivos e não execute comandos que alterem o projeto ou o sistema. Se for preciso mudar algo, descreva o que faria e pergunte antes.",
    permission: "readOnly",
  });
}

// LunaFix: plugin oficial, ativo por padrão. Quando um comando do agente falha, pede a correção antes de entregar a resposta.
// O limite de tentativas fica no app (AUTOFIX_MAX_ATTEMPTS): aqui basta decidir se há o que corrigir.

export function activate(api) {
  api.onTurnDone(({ lastCommand }) => {
    if (!lastCommand || lastCommand.ok) return undefined;
    return [
      "O último comando que você rodou falhou. Antes de dar a tarefa por pronta:",
      "1. Leia a saída do erro abaixo e corrija a causa.",
      "2. Rode o mesmo comando de novo e confirme que passa.",
      "3. Só então responda, dizendo o que mudou.",
      "",
      "Saída do comando:",
      "```",
      lastCommand.output,
      "```",
    ].join("\n");
  });
}
